  test("#given a POSIX staged runtime with a mismatched manifest mode #when checked #then it is stale", async () => {
    const fixture = await makeRuntimeFixture()

    await expect(checkAstGrepMcpRuntimeFresh({ ...fixture, platform: "linux" })).rejects.toThrow(
      "manifest mode 493 does not match staged mode",
    )
  })
})

export interface RuntimeStageOptions {
  readonly repoRoot?: string
  readonly sourceDist?: string
  readonly targetDist?: string
  readonly inputCandidates?: readonly string[]
}

export interface RuntimeStageResult {
  readonly ok: true
  readonly targetDist: string
  readonly manifestPath: string
}

export interface RuntimeVerifyResult {
  readonly ok: true
  readonly version: string
  readonly inputDigest: string
  readonly outputs: readonly { readonly path: string; readonly sha256: string }[]
}

export function stageLspDaemonRuntime(options?: RuntimeStageOptions): Promise<RuntimeStageResult>
export function verifyRuntimeDist(distDir: string): Promise<RuntimeVerifyResult>
export function checkRuntimeDistFresh(options?: RuntimeStageOptions): Promise<RuntimeVerifyResult>

#!/usr/bin/env node
import { createHash } from "node:crypto"
import { existsSync } from "node:fs"
import { access, cp, mkdir, mkdtemp, readFile, readdir, rename, rm, stat, writeFile } from "node:fs/promises"
import { dirname, join, relative, resolve } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const repoRoot = resolve(packageRoot, "..", "..")
const defaultSourceDist = join(repoRoot, "packages", "lsp-daemon", "dist")
const defaultTargetDist = join(pluginRoot, "runtime", "lsp-daemon", "dist")

const REQUIRED_OUTPUTS = [
  "cli.js",
  "index.js",
  "index.d.ts",
  "client.js",
  "client.d.ts",
  "daemon-client.js",
  "daemon-client.d.ts",
  "package.json",
]

const INPUT_CANDIDATES = [
  "packages/lsp-daemon/package.json",
  "packages/lsp-daemon/tsconfig.build.json",
  "packages/lsp-daemon/src",
  "packages/lsp-core/package.json",
  "packages/lsp-core/src",
  "packages/mcp-stdio-core/package.json",
  "packages/mcp-stdio-core/src",
]

const manifestName = ".omo-runtime-manifest.json"

export async function stageLspDaemonRuntime(options = {}) {
  const sourceDist = resolve(options.sourceDist ?? defaultSourceDist)
  const targetDist = resolve(options.targetDist ?? defaultTargetDist)
  const root = resolve(options.repoRoot ?? repoRoot)
  await validateRequiredOutputs(sourceDist)
  const inputDigest = await computeInputDigest(root, options.inputCandidates ?? INPUT_CANDIDATES)
  await mkdir(dirname(targetDist), { recursive: true })
  const tempParent = await mkdtemp(join(dirname(targetDist), ".tmp-omo-senpi-lsp-runtime-"))
  const tempDist = join(tempParent, "dist")
  const backupDist = `${targetDist}.backup-${process.pid}-${Date.now()}`
  let backupCreated = false
  let targetMoved = false

  try {
    await cp(sourceDist, tempDist, { recursive: true, force: true, verbatimSymlinks: true })
    await validateRequiredOutputs(tempDist)
    await writeManifest(tempDist, inputDigest)
    await verifyRuntimeDist(tempDist)
    if (existsSync(targetDist)) {
      await rename(targetDist, backupDist)
      backupCreated = true
    }
    if (process.env.OMO_SENPI_STAGE_FAIL_AFTER_BACKUP === "1") {
      throw new Error("Injected Senpi runtime staging failure after backup")
    }
    await rename(tempDist, targetDist)
    targetMoved = true
    if (backupCreated) await rm(backupDist, { recursive: true, force: true })
    return { ok: true, targetDist, manifestPath: join(targetDist, manifestName) }
  } catch (error) {
    if (!targetMoved && backupCreated) {
      await rm(targetDist, { recursive: true, force: true })
      await rename(backupDist, targetDist)
    }
    throw error
  } finally {
    await rm(tempParent, { recursive: true, force: true })
  }
}

export async function verifyRuntimeDist(distDir) {
  const dist = resolve(distDir)
  await validateRequiredOutputs(dist)
  const manifest = await readRuntimeManifest(dist)
  const outputs = await hashOutputs(dist)
  const actual = JSON.stringify(outputs)
  const expected = JSON.stringify(manifest.outputs)
  if (actual !== expected) {
    throw new Error(`Senpi LSP runtime manifest output hash mismatch at ${join(dist, manifestName)}`)
  }
  return { ok: true, version: manifest.version, inputDigest: manifest.inputDigest, outputs }
}

export async function checkRuntimeDistFresh(options = {}) {
  const root = resolve(options.repoRoot ?? repoRoot)
  const targetDist = resolve(options.targetDist ?? defaultTargetDist)
  const manifest = await readRuntimeManifest(targetDist)
  const expectedInputDigest = await computeInputDigest(root, options.inputCandidates ?? INPUT_CANDIDATES)
  if (manifest.inputDigest !== expectedInputDigest) {
    throw new Error(`Senpi LSP runtime manifest is stale at ${join(targetDist, manifestName)}`)
  }
  return verifyRuntimeDist(targetDist)
}

async function writeManifest(distDir, inputDigest) {
  const packageJson = await readJsonObject(join(distDir, "package.json"))
  const version = stringField(packageJson, "version", join(distDir, "package.json"))
  const manifest = {
    schemaVersion: 1,
    version,
    inputDigest,
    outputs: await hashOutputs(distDir),
  }
  const manifestPath = join(distDir, manifestName)
  const tempPath = `${manifestPath}.${process.pid}.${Date.now()}.tmp`
  await writeFile(tempPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8")
  await rename(tempPath, manifestPath)
}

async function readRuntimeManifest(distDir) {
  const manifestPath = join(distDir, manifestName)
  const manifest = await readJsonObject(manifestPath)
  const schemaVersion = manifest.schemaVersion
  const version = manifest.version
  const inputDigest = manifest.inputDigest
  const outputs = manifest.outputs
  if (schemaVersion !== 1) throw new Error(`Senpi LSP runtime manifest schemaVersion must be 1: ${manifestPath}`)
  if (typeof version !== "string" || version.length === 0) throw new Error(`Senpi LSP runtime manifest version is invalid: ${manifestPath}`)
  if (typeof inputDigest !== "string" || !/^sha256:[0-9a-f]{64}$/.test(inputDigest)) {
    throw new Error(`Senpi LSP runtime manifest inputDigest is invalid: ${manifestPath}`)
  }
  if (!Array.isArray(outputs)) throw new Error(`Senpi LSP runtime manifest outputs must be an array: ${manifestPath}`)
  for (const output of outputs) {
    if (!isRecord(output) || typeof output.path !== "string" || typeof output.sha256 !== "string") {
      throw new Error(`Senpi LSP runtime manifest output entry is invalid: ${manifestPath}`)
    }
    if (!/^[0-9a-f]{64}$/.test(output.sha256)) {
      throw new Error(`Senpi LSP runtime manifest output hash is invalid: ${manifestPath}`)
    }
  }
  const sorted = [...outputs].sort((left, right) => left.path.localeCompare(right.path))
  if (JSON.stringify(sorted) !== JSON.stringify(outputs)) {
    throw new Error(`Senpi LSP runtime manifest outputs must be sorted: ${manifestPath}`)
  }
  return { schemaVersion, version, inputDigest, outputs }
}

async function computeInputDigest(root, candidates) {
  const files = []
  for (const candidate of candidates) {
    const path = join(root, candidate)
    if (await fileExists(path)) files.push(...await listFiles(path))
  }
  files.sort((left, right) => relative(root, left).localeCompare(relative(root, right)))
  const hash = createHash("sha256")
  for (const file of files) {
    hash.update(toPortablePath(relative(root, file)))
    hash.update("\0")
    hash.update(await sha256(file))
    hash.update("\0")
  }
  return `sha256:${hash.digest("hex")}`
}

async function hashOutputs(distDir) {
  const files = (await listFiles(distDir))
    .filter((file) => relative(distDir, file) !== manifestName)
    .sort((left, right) => relative(distDir, left).localeCompare(relative(distDir, right)))
  const outputs = []
  for (const file of files) {
    outputs.push({ path: toPortablePath(relative(distDir, file)), sha256: await sha256(file) })
  }
  return outputs
}

async function validateRequiredOutputs(distDir) {
  for (const output of REQUIRED_OUTPUTS) {
    const path = join(distDir, output)
    let stats
    try {
      stats = await stat(path)
    } catch (error) {
      if (isErrno(error, "ENOENT")) throw new Error(`Senpi LSP runtime is missing ${output} at ${distDir}`)
      throw error
    }
    if (!stats.isFile()) throw new Error(`Senpi LSP runtime output is not a file: ${path}`)
  }
}

async function listFiles(path) {
  const stats = await stat(path)
  if (stats.isFile()) return [path]
  if (!stats.isDirectory()) return []
  const entries = await readdir(path, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const entryPath = join(path, entry.name)
    if (entry.isDirectory()) files.push(...await listFiles(entryPath))
    else if (entry.isFile()) files.push(entryPath)
  }
  return files
}

async function readJsonObject(path) {
  const parsed = JSON.parse(await readFile(path, "utf8"))
  if (!isRecord(parsed)) throw new Error(`${path} must contain a JSON object`)
  return parsed
}

function stringField(record, field, path) {
  const value = record[field]
  if (typeof value !== "string" || value.length === 0) throw new Error(`${path} must contain string field ${field}`)
  return value
}

async function sha256(path) {
  return createHash("sha256").update(await readFile(path)).digest("hex")
}

function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

async function fileExists(path) {
  try {
    await access(path)
    return true
  } catch (error) {
    if (isErrno(error, "ENOENT")) return false
    throw error
  }
}

function isErrno(error, code) {
  return error instanceof Error && "code" in error && error.code === code
}

function toPortablePath(path) {
  return path.replaceAll("\\", "/")
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    if (process.argv.includes("--check")) {
      // Fresh-checkout-safe: if the LSP daemon was never built locally (its dist is a gitignored
      // build output), there is nothing to verify — CI covers the full build in its dedicated job.
      if (!(await fileExists(defaultSourceDist))) {
        console.log(`runtime dist not built locally; skipping freshness check: ${defaultSourceDist}`)
      } else {
        await checkRuntimeDistFresh()
        console.log(`Senpi LSP runtime is current: ${defaultTargetDist}`)
      }
    } else {
      const result = await stageLspDaemonRuntime()
      console.log(`Staged Senpi LSP runtime: ${result.targetDist}`)
    }
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error))
    process.exit(1)
  }
}

#!/usr/bin/env node
import { cp, mkdir, readdir, readFile, rm, stat, writeFile } from "node:fs/promises"
import { dirname, extname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { createNativeSkillSources } from "./native-skill-sources.mjs"
import { insertSenpiCompatibilityGuidance } from "./senpi-compatibility-guidance.mjs"

const pluginRoot = dirname(dirname(fileURLToPath(import.meta.url)))
const repoRoot = dirname(dirname(pluginRoot))
const skillsRoot = join(pluginRoot, "skills")
const sharedSkillsRoot = join(repoRoot, "shared-skills", "skills")

const skillSources = [
  {
    name: "ulw-loop",
    source: join(repoRoot, "omo-senpi", "skills", "ulw-loop"),
  },
]
const componentSkillNames = new Set(skillSources.map(({ name }) => name))

const { sources: nativeSkillSources, names: nativeSkillNames } = createNativeSkillSources(repoRoot)

const textExtensions = new Set([".md", ".yaml", ".yml", ".json", ".txt"])
const sectionHeadingsToStrip = new Set([
  "Codex Harness Tool Compatibility",
  "Codex Tool Mapping",
  "Codex subagent reliability",
  "Codex Subagent Reliability",
  "Subagent-dependent transition barrier",
  "Senpi Harness Tool Compatibility",
])
const forbiddenGuidancePattern = /\b(?:multi_agent|spawn_agent)\b/i

const sourceTestFilePattern = /\.test\.ts$/
const ignoredSkillSourceDirNames = new Set([
  ".mypy_cache",
  ".omo",
  ".pytest_cache",
  ".ruff_cache",
  "__pycache__",
])
const ignoredSkillSourceFileNames = new Set([".gitignore", ".npmignore", "pyrightconfig.json", "openai.yaml"])

function isTextFile(path) {
  return textExtensions.has(extname(path))
}

function rewriteEditionNaming(content) {
  return content
    .replace(/\bon Codex\b/g, "for omo-senpi")
    .replace(/\bIn Codex\b/g, "In omo-senpi")
    .replace(/\bCodex App\b/g, "omo-senpi")
    .replace(/\bCodex CLI\b/g, "omo-senpi")
    .replace(/\bCodex\b/g, "omo-senpi")
    .replace(/\bcodex\b/g, "omo-senpi")
    .replace(/\blazycodex\b/g, "omo-senpi")
    .replace(/\bLazyCodex\b/g, "omo-senpi")
}

function headingLevel(line) {
  const match = line.match(/^(#{1,6})\s+(.+?)\s*$/)
  return match === null ? undefined : match[1].length
}

function headingTitle(line) {
  const match = line.match(/^#{1,6}\s+(.+?)\s*$/)
  return match?.[1]?.replace(/`/g, "").trim()
}

function stripNamedSections(content) {
  const lines = content.split("\n")
  const kept = []
  let strippingLevel

  for (const line of lines) {
    const currentLevel = headingLevel(line)
    if (strippingLevel !== undefined && currentLevel !== undefined && currentLevel <= strippingLevel) {
      strippingLevel = undefined
    }

    if (strippingLevel !== undefined) {
      continue
    }

    const title = headingTitle(line)
    if (title !== undefined && sectionHeadingsToStrip.has(title)) {
      strippingLevel = currentLevel
      continue
    }

    kept.push(line)
  }

  return kept.join("\n")
}

function stripForbiddenGuidanceLines(content) {
  return content
    .split("\n")
    .filter((line) => !forbiddenGuidancePattern.test(line))
    .join("\n")
}

function normalizeBlankLines(content) {
  return content.replace(/\n{3,}/g, "\n\n")
}

function applyTier1Adaptation(content) {
  return normalizeBlankLines(stripForbiddenGuidanceLines(stripNamedSections(rewriteEditionNaming(content))))
}

function applyStartWorkOverlay(content) {
  return content.replace(/codex:<session_id>/g, "senpi:<session_id>").replace(/\bcodex:/g, "senpi:")
}

const ulwPlanReviewOverride = `## Senpi Review Policy (authoritative)

In omo-senpi the high-accuracy review is MOMUS-ONLY: one round is exactly ONE native \`momus\` review of the complete plan file, and a momus approval whose remaining items are notes counts as approval.

Only a plan file produced by this skill and recorded with \`review_required\` authorizes a \`momus\` or \`metis\` review. A bare \`ulw\` run without that file uses notepad self-review instead, however large the work feels.

If a section below conflicts with this section, this section wins.

`

const ulwPlanMomusOnlyRewrites = [
  [
    'The high-accuracy review is DUAL and both passes must return OKAY before handoff: (1) the native \`momus\` reviewer subagent, and (2) an independent Oracle review via \`task(subagent_type="oracle", ...)\` on the strongest available reasoning model, in a fully isolated sub-session with normal approval and sandbox policy. Do not add flags that disable approvals or sandboxing.',
    'In omo-senpi the high-accuracy review is MOMUS-ONLY: one round is exactly ONE native \`momus\` review of the complete plan file.',
  ],
  ["### High-accuracy review (dual review)", "### High-accuracy review (momus-only in omo-senpi)"],
  [
    'One round = exactly ONE \`momus\` + ONE independent review, dispatched together',
    'One round = exactly ONE \`momus\` review, dispatched',
  ],
  ['"independent_reviewer": "oracle",', '"independent_reviewer": null,'],
  ['"lanes": ["momus", "independent"],', '"lanes": ["momus"],'],
  [
    '(all read-only, plus \`oracle\` for the high-accuracy review)',
    '(all read-only; \`momus\` also runs the high-accuracy review)',
  ],
  [
    'the dual high-accuracy review (native \`momus\` + the independent Oracle review) is now REQUIRED',
    'the high-accuracy review (momus-only in omo-senpi) is now REQUIRED',
  ],
]

function rewriteUlwPlanReviewToMomusOnly(content) {
  let rewritten = content
  for (const [source, replacement] of ulwPlanMomusOnlyRewrites) {
    rewritten = rewritten.replaceAll(source, replacement)
  }
  return rewritten
}

const ulwPlanConsultationLanes = `## Senpi Design Consultation Lanes (authoritative)

When the task tool's available categories include \`architect\` and/or \`ultrabrain\`, ACTIVELY consult them as background advisory lanes while grounding and drafting the plan:

| Lane | Category | Ask it for |
| --- | --- | --- |
| Big-picture design | \`architect\` | module boundaries, decomposition options, trade-offs, blast radius |
| Detail design | \`ultrabrain\` | algorithms, edge cases, exact interfaces and contracts |

Spawn them with \`task(category: "architect" \\| "ultrabrain", run_in_background: true)\` in the same wave as your research lanes, and integrate their answers before the approval brief. Every such prompt MUST start with TASK / DELIVERABLE / SCOPE / VERIFY / STOP WHEN and MUST declare itself advisory-only: read-only analysis, NO file edits, recommendations returned as text. Treat what comes back as claims to verify, not as decisions already made.

This section is an EXPLICIT EXCEPTION to the later rule "Never dispatch with \`category=\`": it authorizes exactly these two advisory lanes. Every other category dispatch stays forbidden. When neither category is listed as available, skip these lanes silently.

`

function applyUlwPlanOverlay(content) {
  const rewritten = rewriteUlwPlanReviewToMomusOnly(content)
  if (rewritten.includes("# ulw-plan - full workflow")) {
    return insertAfterFrontmatter(rewritten, ulwPlanReviewOverride)
  }
  if (/^#\s+ulw-plan\s*$/m.test(rewritten)) {
    return insertAfterFrontmatter(rewritten, `${ulwPlanReviewOverride}${ulwPlanConsultationLanes}`)
  }
  return rewritten
}

function insertAfterFrontmatter(content, section) {
  const frontmatterEnd = content.indexOf("\n---\n", content.startsWith("---\n") ? 4 : 0)
  if (!content.startsWith("---\n") || frontmatterEnd === -1) return `${section}${content}`
  const insertAt = frontmatterEnd + "\n---\n".length
  return `${content.slice(0, insertAt)}\n${section}${content.slice(insertAt)}`
}

function applySharedTierAdaptation(skillName, content) {
  let adapted = content
  if (skillName === "start-work") {
    adapted = applyStartWorkOverlay(adapted)
  }
  if (skillName === "ulw-plan") {
    adapted = applyUlwPlanOverlay(adapted)
  }
  adapted = stripNamedSections(adapted)
  adapted = stripForbiddenGuidanceLines(adapted)
  adapted = insertSenpiCompatibilityGuidance(adapted)
  return normalizeBlankLines(adapted)
}

function shouldCopySkillSource(source) {
  const normalized = source.replaceAll("\\", "/")
  const segments = normalized.split("/")
  const name = segments.at(-1) ?? ""
  if (segments.some((segment) => ignoredSkillSourceDirNames.has(segment))) return false
  if (ignoredSkillSourceFileNames.has(name)) return false
  if (sourceTestFilePattern.test(name) || name.endsWith(".pyc")) return false
  const scriptsIndex = segments.lastIndexOf("scripts")
  return scriptsIndex === -1 || segments[scriptsIndex + 1] !== "tests"
}

async function listFiles(root) {
  const entries = await readdir(root, { withFileTypes: true })
  const files = []

  for (const entry of entries) {
    const entryPath = join(root, entry.name)
    if (entry.isDirectory()) {
      files.push(...(await listFiles(entryPath)))
    } else if (entry.isFile()) {
      files.push(entryPath)
    }
  }

  return files
}

async function adaptSkillTree(skillRoot, adapter) {
  const files = await listFiles(skillRoot)
  for (const file of files) {
    if (!isTextFile(file)) continue

    const before = await readFile(file, "utf8")
    const after = adapter(before)
    if (after !== before) {
      await writeFile(file, after, "utf8")
    }
  }
}

async function assertSourceExists(source) {
  const sourceStat = await stat(source)
  if (!sourceStat.isDirectory()) {
    throw new Error(`${source} is not a directory`)
  }
}

export async function syncSkills() {
  await rm(skillsRoot, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })
  await mkdir(skillsRoot, { recursive: true })

  for (const { name, source } of skillSources) {
    await assertSourceExists(source)
    const destination = join(skillsRoot, name)
    await cp(source, destination, { filter: shouldCopySkillSource, recursive: true })
    await adaptSkillTree(destination, normalizeBlankLines)
  }

  for (const { name, source } of nativeSkillSources) {
    await assertSourceExists(source)
    const destination = join(skillsRoot, name)
    await cp(source, destination, { filter: shouldCopySkillSource, recursive: true })
    await adaptSkillTree(destination, normalizeBlankLines)
  }

  const sharedSkillEntries = await readdir(sharedSkillsRoot, { withFileTypes: true })
  const sharedSkillNames = sharedSkillEntries
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort()

  for (const skillName of sharedSkillNames) {
    if (componentSkillNames.has(skillName) || nativeSkillNames.has(skillName)) continue
    const source = join(sharedSkillsRoot, skillName)
    const destination = join(skillsRoot, skillName)
    await cp(source, destination, { filter: shouldCopySkillSource, recursive: true })
    await adaptSkillTree(destination, (content) => applySharedTierAdaptation(skillName, content))
  }

  console.log(`synced omo-senpi skills to ${skillsRoot}`)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await syncSkills()
}

#!/usr/bin/env node
import { readFile, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const adapterManifestPath = join(packageRoot, "package.json")
const pluginManifestPath = join(pluginRoot, "package.json")

async function readJson(path) {
  return JSON.parse(await readFile(path, "utf8"))
}

async function writeJson(path, value) {
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`)
}

export async function syncVersion(options = {}) {
  const adapterManifest = await readJson(options.adapterManifestPath ?? adapterManifestPath)
  const pluginManifest = await readJson(options.pluginManifestPath ?? pluginManifestPath)
  const version = adapterManifest.version
  if (typeof version !== "string" || version.length === 0) {
    throw new Error("Cannot sync omo-senpi plugin version: adapter package.json has no version")
  }

  const changed = pluginManifest.version !== version
  if (changed && options.check === true) {
    return { ok: false, version, current: pluginManifest.version }
  }
  if (changed) {
    pluginManifest.version = version
    await writeJson(options.pluginManifestPath ?? pluginManifestPath, pluginManifest)
  }
  return { ok: true, version, changed }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const result = await syncVersion({ check: process.argv.includes("--check") })
  if (!result.ok) {
    console.error(`omo-senpi plugin/package.json version mismatch: expected ${result.version}, found ${result.current}`)
    process.exit(1)
  }
  console.log(`omo-senpi plugin/package.json version ${result.version}${result.changed ? " synced" : " current"}`)
}
